/**
 * Drift guard: the app-served copy of the checker must match the tested source in `ui/public/`.
 *
 * `public/checker/*`, the woff2 fonts under `public/fonts/` and `src/app/checker/shell.generated.ts`
 * are all generated by `ui/scripts/sync-public.ts`. A source change without regeneration fails here,
 * so the screen users see cannot silently diverge from the assets the suite proves.
 *
 * Runner: Node built-in `node --test` (zero dependencies), same as the rest of the M4 suite.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

test('the app-served checker copy is byte-identical to its tested source', () => {
  const script = fileURLToPath(new URL('./scripts/sync-public.ts', import.meta.url));
  const output = execFileSync(process.execPath, [script, '--check'], { encoding: 'utf8' });
  assert.match(output, /Served checker copy verified/);
});
